sp_widget.script:
(function() { data.dependencies = []; data.templateId = $sp.getParameter("template_id") || "";
  try { if (!data.templateId) return;
    if (input && input.action === "add_dep") { var dGr = new GlideRecord("x_1433041_identi_0_dependency"); dGr.initialize(); dGr.setValue("template", data.templateId); dGr.setValue("source_question", input.source); dGr.setValue("target_question", input.target); dGr.setValue("condition", input.condition || "equals"); dGr.setValue("value", input.value || ""); dGr.insert(); }
    var gr = new GlideRecord("x_1433041_identi_0_dependency"); gr.addQuery("template", data.templateId); gr.orderByDesc("sys_created_on"); gr.setLimit(50); gr.query();
    while (gr.next()) { data.dependencies.push({ sys_id: gr.getValue("sys_id"), source: gr.getDisplayValue("source_question"), target: gr.getDisplayValue("target_question"), condition: gr.getDisplayValue("condition"), value: gr.getValue("value") }); }
  } catch (e) { gs.error("IBAR Dependency Form widget error: " + e.message); }
})();
